def solve(pc, pr, rc, rr, beta):
    import math
    if not all(math.isfinite(x) for x in (pc,pr,rc,rr,beta)) or beta<=0: raise ValueError('inputs')
    z=beta*((pc-pr)-(rc-rr))
    return max(-z,0)+math.log1p(math.exp(-abs(z)))

